SELECT 'WA_WR_BEFORE_B_GENUINE_LEASED_GROUP';
UPDATE platform.runtime_command_receipt SET state='committed',result_digest=encode(sha256(convert_to('{"outcome":"enrolled","selectionRevision":"0","receipt":"be2aa578-598a-5aae-9ffb-6caea3f701ea"}'::jsonb::text,'UTF8')),'hex'),result_body='{"outcome":"enrolled","selectionRevision":"0","receipt":"be2aa578-598a-5aae-9ffb-6caea3f701ea"}'::jsonb WHERE id='c7fe92b9-2ef9-5892-bf43-794f3cf9d802' AND state='pending';
-- Actual wa_worker, new tuple-bound processing grant, same connection/xid through COMMIT.
UPDATE platform.runtime_work_item SET effect_receipt_id='c29de844-e0cd-5e7c-b5bc-4f7c11b1de2e' WHERE id='bd16c4aa-52bd-50f6-950e-c55e501f2b21' AND fence=1 AND state='leased' AND effect_receipt_id IS NULL;
SELECT 'WA_WORKER_EFFECT_LINKED';
SELECT 'WA_WORKER_GROUP_STAGED';
SET CONSTRAINTS ALL IMMEDIATE;
SELECT 'WA_WORKER_CONSTRAINTS_CHECKED';
SELECT jsonb_build_object('linked_effect_matches',platform_private.worker_effect_matches('bd16c4aa-52bd-50f6-950e-c55e501f2b21','c29de844-e0cd-5e7c-b5bc-4f7c11b1de2e',true),'still_leased',(SELECT state='leased' FROM platform.runtime_work_item WHERE id='bd16c4aa-52bd-50f6-950e-c55e501f2b21'));
SELECT 'WA_WR_AFTER_B_GENUINE_LEASED_GROUP';
COMMIT;
